-- 초기 스키마: docs/erd/physical-erd.dbml(물리 ERD 설계안)을 PostgreSQL DDL로 옮긴 것
-- 이후 변경은 새 마이그레이션 파일로 추가한다(파일명 V{yyyyMMdd_HHmm}__설명.sql, out-of-order 허용)

CREATE TABLE "organization" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" varchar(80) NOT NULL,
  "name" varchar(200) NOT NULL,
  "active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("id")
);

CREATE TABLE "app_user" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" varchar(320) NOT NULL,
  "name" varchar(200) NOT NULL,
  "role" varchar(30) NOT NULL,
  "organization_id" bigint,
  "active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "app_user_check" CHECK ((((role = 'PLANNER') AND (organization_id IS NULL)) OR ((role = 'ORG_MANAGER') AND (organization_id IS NOT NULL)))),
  CONSTRAINT "app_user_role_check" CHECK (role IN ('PLANNER', 'ORG_MANAGER')),
  PRIMARY KEY ("id")
);

CREATE TABLE "annual_plan" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "year" integer NOT NULL,
  "status" varchar(20) NOT NULL,
  "confirmed_by" bigint,
  "confirmed_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "annual_plan_status_check" CHECK (status IN ('COLLECTING', 'CONFIRMED')),
  CONSTRAINT "annual_plan_year_check" CHECK (((year >= 2000) AND (year <= 9999))),
  PRIMARY KEY ("id")
);

CREATE TABLE "submission_request" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "annual_plan_id" bigint NOT NULL,
  "type" varchar(30) NOT NULL,
  "month" integer,
  "status" varchar(10) NOT NULL,
  "message" text,
  "due_at" timestamptz,
  "requested_by" bigint NOT NULL,
  "requested_at" timestamptz NOT NULL,
  "period_key" varchar(30) NOT NULL,
  CONSTRAINT "submission_request_check" CHECK ((((type = 'ANNUAL_PLAN') AND (month IS NULL)) OR ((type = 'MONTHLY_ACTUAL') AND (month IS NOT NULL)))),
  CONSTRAINT "submission_request_month_check" CHECK (((month >= 1) AND (month <= 12))),
  CONSTRAINT "submission_request_status_check" CHECK (status IN ('OPEN', 'CLOSED')),
  CONSTRAINT "submission_request_type_check" CHECK (type IN ('ANNUAL_PLAN', 'MONTHLY_ACTUAL')),
  PRIMARY KEY ("id")
);

CREATE TABLE "request_target" (
  "request_id" bigint NOT NULL,
  "organization_id" bigint NOT NULL,
  "confirmed_plan_submission_id" bigint,
  "excluded" boolean NOT NULL DEFAULT false,
  "selected" boolean NOT NULL DEFAULT true,
  PRIMARY KEY ("request_id", "organization_id")
);

CREATE TABLE "stored_object" (
  "object_key" varchar(100) NOT NULL,
  "content_type" varchar(100) NOT NULL,
  "size_bytes" bigint NOT NULL,
  "sha256" char(64) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  PRIMARY KEY ("object_key")
);

CREATE TABLE "submission" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "request_id" bigint NOT NULL,
  "organization_id" bigint NOT NULL,
  "seq" integer,
  "status" varchar(20) NOT NULL,
  "original_filename" varchar(255) NOT NULL,
  "source_object_key" varchar(100) NOT NULL,
  "source_sha256" char(64) NOT NULL,
  "uploaded_by" bigint NOT NULL,
  "uploaded_at" timestamptz NOT NULL,
  "submitted_by" bigint,
  "submitted_at" timestamptz,
  "reviewed_by" bigint,
  "reviewed_at" timestamptz,
  "reject_reason" text,
  "previous_submission_id" bigint,
  "reply_message" text,
  "approved_seq" integer,
  CONSTRAINT "submission_check" CHECK ((((status = 'DRAFT') AND (seq IS NULL)) OR ((status <> 'DRAFT') AND (seq IS NOT NULL) AND (seq > 0)))),
  CONSTRAINT "submission_status_check" CHECK (status IN ('DRAFT', 'PENDING', 'REJECTED', 'APPROVED')),
  CONSTRAINT "submission_approved_seq_check" CHECK (((status = 'APPROVED') = (approved_seq IS NOT NULL))),
  PRIMARY KEY ("id")
);

CREATE TABLE "parsing_job" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "submission_id" bigint NOT NULL,
  "status" varchar(20) NOT NULL,
  "engine" varchar(80) NOT NULL,
  "parser_version" varchar(80),
  "contract_version" varchar(80),
  "mapping_version" varchar(80),
  "attempt_no" integer NOT NULL,
  "result_object_key" varchar(100),
  "error_code" varchar(100),
  "error_message" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "started_at" timestamptz,
  "finished_at" timestamptz,
  CONSTRAINT "parsing_job_attempt_no_check" CHECK ((attempt_no > 0)),
  CONSTRAINT "parsing_job_status_check" CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')),
  PRIMARY KEY ("id")
);

CREATE TABLE "idempotency_record" (
  "actor_id" bigint NOT NULL,
  "route" varchar(200) NOT NULL,
  "idempotency_key" varchar(128) NOT NULL,
  "fingerprint" char(64) NOT NULL,
  "response_status" integer NOT NULL,
  "response_body" text NOT NULL,
  "location" varchar(200) NOT NULL,
  "expires_at" timestamptz NOT NULL,
  PRIMARY KEY ("actor_id", "route", "idempotency_key")
);

CREATE TABLE "account_item" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "source_type" varchar(30) NOT NULL,
  "source_code" varchar(160) NOT NULL,
  "source_name" varchar(500) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "account_item_source_type_check" CHECK (source_type IN ('REVENUE_CLASS', 'EXPENSE_BUDGET')),
  PRIMARY KEY ("id")
);

CREATE TABLE "report_item" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" varchar(160) NOT NULL,
  "name" varchar(500) NOT NULL,
  "parent_id" bigint,
  "kind" varchar(20) NOT NULL,
  "is_leaf" boolean NOT NULL,
  "calculation_code" varchar(80),
  "display_order" integer NOT NULL DEFAULT 0,
  "active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "report_item_kind_check" CHECK (kind IN ('REVENUE', 'COST', 'DERIVED')),
  PRIMARY KEY ("id")
);

CREATE TABLE "financial_line" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "submission_id" bigint NOT NULL,
  "account_item_id" bigint,
  "report_item_id" bigint NOT NULL,
  "detail_id" varchar(500),
  "detail_revision" varchar(80),
  "headquarters_code" varchar(160),
  "team_code" varchar(160),
  "task_code" varchar(160),
  "management_category" varchar(500),
  "actual_basis" varchar(500),
  "cost_type" varchar(500),
  "description" text,
  "source_sheet" varchar(255) NOT NULL,
  "source_row" integer NOT NULL,
  CONSTRAINT "financial_line_source_row_check" CHECK ((source_row > 0)),
  PRIMARY KEY ("id")
);

CREATE TABLE "financial_value" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "line_id" bigint NOT NULL,
  "year" integer NOT NULL,
  "month" integer NOT NULL,
  "scenario" varchar(20) NOT NULL,
  "amount" numeric(30,6) NOT NULL,
  "source_record_id" varchar(500) NOT NULL,
  "source_cell" varchar(30) NOT NULL,
  CONSTRAINT "financial_value_month_check" CHECK (((month >= 1) AND (month <= 12))),
  CONSTRAINT "financial_value_scenario_check" CHECK (scenario IN ('PLAN', 'ACTUAL', 'ESTIMATE')),
  CONSTRAINT "financial_value_year_check" CHECK (((year >= 2000) AND (year <= 9999))),
  PRIMARY KEY ("id")
);

CREATE TABLE "submission_validation" (
  "submission_id" bigint NOT NULL,
  "attempt_no" integer NOT NULL,
  "source_sha256" char(64) NOT NULL,
  "parser_result_object_key" varchar(100) NOT NULL,
  "policy_version" varchar(80) NOT NULL,
  "validation_result_object_key" varchar(100) NOT NULL,
  "validated_by" bigint NOT NULL,
  "validated_at" timestamptz NOT NULL,
  CONSTRAINT "submission_validation_attempt_no_check" CHECK ((attempt_no > 0)),
  PRIMARY KEY ("submission_id")
);

CREATE TABLE "annual_master" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "request_id" bigint NOT NULL,
  "seq" integer NOT NULL,
  "previous_master_id" bigint,
  "trigger_submission_id" bigint NOT NULL,
  "content_sha256" char(64) NOT NULL,
  "calculation_version" varchar(80) NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "annual_master_seq_check" CHECK ((seq > 0)),
  PRIMARY KEY ("id")
);

CREATE TABLE "annual_master_source" (
  "master_id" bigint NOT NULL,
  "organization_id" bigint NOT NULL,
  "submission_id" bigint NOT NULL,
  PRIMARY KEY ("master_id", "organization_id")
);

CREATE TABLE "master_version" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "request_id" bigint NOT NULL,
  "seq" integer NOT NULL,
  "previous_master_id" bigint,
  "trigger_submission_id" bigint NOT NULL,
  "content_sha256" char(64) NOT NULL,
  "calculation_version" varchar(80) NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL,
  CONSTRAINT "master_version_seq_check" CHECK ((seq > 0)),
  PRIMARY KEY ("id")
);

CREATE TABLE "master_source" (
  "master_id" bigint NOT NULL,
  "organization_id" bigint NOT NULL,
  "submission_id" bigint NOT NULL,
  PRIMARY KEY ("master_id", "organization_id")
);

CREATE TABLE "gap_threshold" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "comparison" varchar(30) NOT NULL,
  "percent" numeric(30,6) NOT NULL,
  "amount" numeric(30,6) NOT NULL,
  "applied_by" bigint NOT NULL,
  "applied_at" timestamptz NOT NULL,
  "percent_enabled" boolean NOT NULL DEFAULT true,
  "amount_enabled" boolean NOT NULL DEFAULT true,
  CONSTRAINT "ck_gap_threshold_enabled" CHECK ((percent_enabled OR amount_enabled)),
  CONSTRAINT "gap_threshold_amount_check" CHECK ((amount >= 0)),
  CONSTRAINT "gap_threshold_percent_check" CHECK ((percent >= 0)),
  CONSTRAINT "gap_threshold_comparison_check" CHECK (comparison IN ('ACTUAL_VS_PLAN', 'ESTIMATE_VS_PREVIOUS', 'ESTIMATE_VS_PLAN')),
  PRIMARY KEY ("id")
);

CREATE TABLE "review_item" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "submission_id" bigint NOT NULL,
  "report_item_id" bigint NOT NULL,
  "year" integer NOT NULL,
  "month" integer NOT NULL,
  "scenario" varchar(20) NOT NULL,
  "amount_present" boolean NOT NULL,
  "current_amount" numeric(48,6),
  "change_detected" boolean NOT NULL,
  "gap_exceeded" boolean NOT NULL,
  "source_fingerprint" char(64) NOT NULL,
  "context_fingerprint" char(64) NOT NULL,
  "current_round" integer NOT NULL,
  "active" boolean NOT NULL DEFAULT true,
  "review_policy_version" varchar(80) NOT NULL DEFAULT 'legacy/1.0',
  "workflow_state" varchar(30) NOT NULL DEFAULT 'NEEDS_REVIEW',
  "workflow_note" varchar(4000),
  "rejected" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "review_item_check" CHECK (((amount_present AND (current_amount IS NOT NULL)) OR ((NOT amount_present) AND (current_amount IS NULL)))),
  CONSTRAINT "review_item_current_round_check" CHECK ((current_round > 0)),
  CONSTRAINT "review_item_month_check" CHECK (((month >= 1) AND (month <= 12))),
  CONSTRAINT "review_item_scenario_check" CHECK (scenario IN ('PLAN', 'ACTUAL', 'ESTIMATE')),
  CONSTRAINT "review_item_workflow_state_check" CHECK (workflow_state IN ('NEEDS_REVIEW', 'SELECTED', 'REQUESTED', 'EXCLUDED')),
  PRIMARY KEY ("id")
);

CREATE TABLE "gap_comparison" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "review_item_id" bigint NOT NULL,
  "basis" varchar(20) NOT NULL,
  "baseline_submission_id" bigint NOT NULL,
  "baseline_scenario" varchar(20) NOT NULL,
  "baseline_amount" numeric(48,6) NOT NULL,
  "current_amount" numeric(48,6) NOT NULL,
  "gap_amount" numeric(49,6) NOT NULL,
  "gap_rate" numeric(60,8),
  "threshold_id" bigint NOT NULL,
  "exceeded" boolean NOT NULL,
  CONSTRAINT "gap_comparison_baseline_scenario_check" CHECK (baseline_scenario IN ('PLAN', 'ACTUAL', 'ESTIMATE')),
  CONSTRAINT "gap_comparison_basis_check" CHECK (basis IN ('PLAN', 'PREVIOUS')),
  PRIMARY KEY ("id")
);

CREATE TABLE "review_explanation" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "review_item_id" bigint NOT NULL,
  "round" integer NOT NULL,
  "request_note" varchar(4000),
  "requested_by" bigint,
  "requested_at" timestamptz,
  "answer" varchar(4000),
  "answered_by" bigint,
  "answered_at" timestamptz,
  "verdict" varchar(20) NOT NULL,
  "reviewed_by" bigint,
  "reviewed_at" timestamptz,
  "review_note" varchar(4000),
  "inherited_from_id" bigint,
  "due_at" timestamptz,
  "attachment_revision" bigint NOT NULL DEFAULT 0,
  CONSTRAINT "review_explanation_round_check" CHECK ((round > 0)),
  CONSTRAINT "review_explanation_verdict_check" CHECK (verdict IN ('PENDING', 'ACCEPTED', 'REJECTED')),
  PRIMARY KEY ("id")
);

CREATE TABLE "gap_threshold_guard" (
  "id" integer NOT NULL,
  CONSTRAINT "gap_threshold_guard_id_check" CHECK ((id = 1)),
  PRIMARY KEY ("id")
);

CREATE TABLE "review_workflow_event" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "review_item_id" bigint NOT NULL,
  "action" varchar(30) NOT NULL,
  "explanation_round" integer NOT NULL,
  "note" varchar(4000),
  "due_at" timestamptz,
  "acted_by" bigint NOT NULL,
  "acted_at" timestamptz NOT NULL,
  CONSTRAINT "review_workflow_event_action_check" CHECK (action IN ('SELECT', 'EXCLUDE', 'REQUEST_EXPLANATION')),
  PRIMARY KEY ("id")
);

CREATE TABLE "notification" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "recipient_id" bigint NOT NULL,
  "type" varchar(20) NOT NULL,
  "event_key" varchar(180) NOT NULL,
  "request_id" bigint NOT NULL,
  "organization_id" bigint NOT NULL,
  "submission_id" bigint,
  "review_explanation_id" bigint,
  "title" varchar(300) NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "read_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "notification_type_check" CHECK (type IN ('SUBMISSION', 'REPLY', 'OVERDUE')),
  PRIMARY KEY ("id")
);

CREATE TABLE "request_template" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "request_id" bigint NOT NULL,
  "object_key" varchar(100) NOT NULL,
  "filename" varchar(255) NOT NULL,
  "source_sha256" char(64) NOT NULL,
  "registered_by" bigint NOT NULL,
  "registered_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "review_attachment" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "explanation_id" bigint NOT NULL,
  "original_filename" varchar(255) NOT NULL,
  "content_type" varchar(100) NOT NULL,
  "byte_size" bigint NOT NULL,
  "sha256" char(64) NOT NULL,
  "object_key" varchar(100) NOT NULL,
  "uploaded_by" bigint NOT NULL,
  "uploaded_at" timestamptz NOT NULL,
  CONSTRAINT "review_attachment_byte_size_check" CHECK (((byte_size >= 1) AND (byte_size <= 16777216))),
  PRIMARY KEY ("id")
);

CREATE TABLE "pdf_job" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "requested_by" bigint NOT NULL,
  "source_object_key" varchar(100) NOT NULL,
  "mask_numbers" boolean NOT NULL DEFAULT true,
  "status" varchar(20) NOT NULL,
  "attempt_no" integer NOT NULL DEFAULT 1,
  "result_object_key" varchar(100),
  "error_code" varchar(100),
  "error_message" text,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "started_at" timestamptz,
  "finished_at" timestamptz,
  CONSTRAINT "pdf_job_status_check" CHECK (status IN ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED')),
  CONSTRAINT "pdf_job_attempt_no_check" CHECK ((attempt_no > 0)),
  PRIMARY KEY ("id")
);

CREATE TABLE "report_template" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(200) NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "active" boolean NOT NULL DEFAULT true,
  PRIMARY KEY ("id")
);

CREATE TABLE "report_template_version" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "template_id" bigint NOT NULL,
  "version" integer NOT NULL,
  "source_pdf_job_id" bigint,
  "definition" jsonb NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "report_template_version_version_check" CHECK ((version > 0)),
  PRIMARY KEY ("id")
);

CREATE TABLE "metric" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" varchar(80) NOT NULL,
  "name" varchar(200) NOT NULL,
  "description" text,
  "sql_text" text NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "active" boolean NOT NULL DEFAULT true,
  PRIMARY KEY ("id")
);

CREATE TABLE "explanation_category" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "table_version" integer NOT NULL,
  "code" integer NOT NULL,
  "name" varchar(100) NOT NULL,
  "display_order" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE TABLE "explanation_classification" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "review_explanation_id" bigint NOT NULL,
  "category_id" bigint NOT NULL,
  "classified_by" bigint NOT NULL,
  "classified_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "organization_code_key" ON "organization" ("code");

CREATE UNIQUE INDEX "app_user_email_key" ON "app_user" ("email");

CREATE UNIQUE INDEX "annual_plan_year_key" ON "annual_plan" ("year");

CREATE UNIQUE INDEX "submission_request_period_key_key" ON "submission_request" ("period_key");

CREATE UNIQUE INDEX "submission_request_id_organization_id_seq_key" ON "submission" ("request_id", "organization_id", "seq");

CREATE UNIQUE INDEX "submission_approved_seq_key" ON "submission" ("request_id", "organization_id", "approved_seq");

CREATE INDEX "ix_submission_org_time" ON "submission" USING BTREE ("organization_id", "uploaded_at", "id");

CREATE UNIQUE INDEX "parsing_job_submission_id_key" ON "parsing_job" ("submission_id");

CREATE INDEX "ix_job_queue" ON "parsing_job" USING BTREE ("status", "id");

CREATE UNIQUE INDEX "account_item_source_type_source_code_source_name_key" ON "account_item" ("source_type", "source_code", "source_name");

CREATE UNIQUE INDEX "report_item_code_key" ON "report_item" ("code");

CREATE UNIQUE INDEX "financial_line_submission_id_source_sheet_source_row_key" ON "financial_line" ("submission_id", "source_sheet", "source_row");

CREATE INDEX "ix_financial_line_report" ON "financial_line" USING BTREE ("submission_id", "report_item_id", "id");

CREATE UNIQUE INDEX "financial_value_line_id_year_month_scenario_key" ON "financial_value" ("line_id", "year", "month", "scenario");

CREATE INDEX "ix_financial_value_period" ON "financial_value" USING BTREE ("year", "month", "scenario", "line_id");

CREATE UNIQUE INDEX "annual_master_request_id_seq_key" ON "annual_master" ("request_id", "seq");

CREATE UNIQUE INDEX "annual_master_source_master_id_submission_id_key" ON "annual_master_source" ("master_id", "submission_id");

CREATE INDEX "ix_annual_master_source_submission" ON "annual_master_source" USING BTREE ("submission_id");

CREATE UNIQUE INDEX "master_version_request_id_seq_key" ON "master_version" ("request_id", "seq");

CREATE UNIQUE INDEX "master_source_master_id_submission_id_key" ON "master_source" ("master_id", "submission_id");

CREATE INDEX "ix_master_source_submission" ON "master_source" USING BTREE ("submission_id");

CREATE INDEX "ix_threshold_latest" ON "gap_threshold" USING BTREE ("comparison", "id" DESC);

CREATE UNIQUE INDEX "review_item_submission_id_report_item_id_year_month_scenari_key" ON "review_item" ("submission_id", "report_item_id", "year", "month", "scenario");

CREATE INDEX "ix_review_submission_active" ON "review_item" USING BTREE ("submission_id", "active");

CREATE UNIQUE INDEX "gap_comparison_review_item_id_basis_key" ON "gap_comparison" ("review_item_id", "basis");

CREATE UNIQUE INDEX "review_explanation_review_item_id_round_key" ON "review_explanation" ("review_item_id", "round");

CREATE INDEX "ix_review_workflow_event" ON "review_workflow_event" USING BTREE ("review_item_id", "id");

CREATE UNIQUE INDEX "notification_recipient_event_key" ON "notification" ("recipient_id", "event_key");

CREATE INDEX "ix_notification_inbox" ON "notification" USING BTREE ("recipient_id", "read_at", "occurred_at");

CREATE INDEX "ix_request_template_latest" ON "request_template" USING BTREE ("request_id", "id" DESC);

CREATE UNIQUE INDEX "review_attachment_object_key_key" ON "review_attachment" ("object_key");

CREATE INDEX "ix_review_attachment_round" ON "review_attachment" USING BTREE ("explanation_id", "id");

CREATE INDEX "ix_pdf_job_queue" ON "pdf_job" USING BTREE ("status", "id");

CREATE UNIQUE INDEX "report_template_version_key" ON "report_template_version" ("template_id", "version");

CREATE UNIQUE INDEX "metric_code_key" ON "metric" ("code");

CREATE UNIQUE INDEX "explanation_category_key" ON "explanation_category" ("table_version", "code");

CREATE UNIQUE INDEX "explanation_classification_key" ON "explanation_classification" ("review_explanation_id");

ALTER TABLE "app_user" ADD CONSTRAINT "app_user_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "annual_plan" ADD CONSTRAINT "annual_plan_confirmed_by_fkey" FOREIGN KEY ("confirmed_by") REFERENCES "app_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "submission_request" ADD CONSTRAINT "submission_request_annual_plan_id_fkey" FOREIGN KEY ("annual_plan_id") REFERENCES "annual_plan" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "submission_request" ADD CONSTRAINT "submission_request_requested_by_fkey" FOREIGN KEY ("requested_by") REFERENCES "app_user" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "request_target" ADD CONSTRAINT "request_target_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization" ("id") DEFERRABLE INITIALLY IMMEDIATE;

